const VOCAB_TRACK = "honors";
const VOCAB_UNITS = [{"unit":1,"title":"Introduction to Functions in Algebra II","terms":[{"term":"domain","def":"The set of all possible input values (x-values) a function can use."},{"term":"range","def":"The set of all possible output values (y-values) a function can produce."},{"term":"set notation","def":"Writing a domain or range using braces and a \"such that\" bar, e.g. {x | x ≥ 0}."},{"term":"interval notation","def":"Writing a range of values using brackets/parentheses, e.g. [0, ∞) — bracket if included, parenthesis if excluded, ∞ always gets a parenthesis."},{"term":"inequality notation","def":"Writing domain or range using \u003c, ≤, \u003e, or ≥ instead of interval or set notation, e.g. x ≥ 0."},{"term":"continuous function","def":"The graph is unbroken — you could trace it without ever lifting your pencil."},{"term":"discrete function","def":"The graph is made of separate, disconnected points — nothing connects them."},{"term":"reflectional symmetry","def":"The graph can be folded across a line and land exactly on itself, e.g. |x| folds across the y-axis."},{"term":"x-intercept(s)","def":"The point(s) where a graph crosses the x-axis. There, y = 0."},{"term":"y-intercept(s)","def":"The point where a graph crosses the y-axis. There, x = 0."},{"term":"zeros","def":"The x-value(s) that make a function equal 0 — the same locations as the x-intercepts."},{"term":"asymptotic behavior","def":"How a graph behaves near a value it gets closer and closer to but never reaches."},{"term":"horizontal asymptote","def":"A horizontal line that a graph\u0027s y-values get closer and closer to, without touching, as x gets very large or very small."},{"term":"vertical asymptote","def":"A vertical line the graph gets closer and closer to but never crosses — it marks where the function is undefined."},{"term":"inverse of a function","def":"The function that undoes the original — written f⁻¹(x). Swap x and y in a table; reflect across y = x on a graph."},{"term":"composition of functions","def":"Putting one function inside another and evaluating: f(g(x)), read \"f of g of x.\" Work from the inside out."},{"term":"absolute value function","def":"The parent function f(x) = |x|."},{"term":"cube root function","def":"The parent function f(x) = ∛x."},{"term":"cubic function","def":"The parent function f(x) = x³."},{"term":"decreasing function","def":"As x increases, y gets smaller — the graph falls from left to right over that interval."},{"term":"dependent variable","def":"The output of a function — it depends on what you put in. Goes on the y-axis."},{"term":"exponential function","def":"A function of the form f(x) = bˣ."},{"term":"function notation","def":"Writing a function as f(x) instead of y — read \"f of x.\""},{"term":"increasing function","def":"As x increases, y also gets bigger — the graph rises from left to right over that interval."},{"term":"independent variable","def":"The input of a function — the value you choose. Goes on the x-axis."},{"term":"linear function","def":"The parent function f(x) = x."},{"term":"logarithmic function","def":"A function of the form f(x) = log_b(x)."},{"term":"quadratic function","def":"The parent function f(x) = x²."},{"term":"rational function","def":"The parent function f(x) = 1/x."},{"term":"relation","def":"Any set of ordered pairs (x, y). Every function is a relation, but not every relation is a function."},{"term":"representations","def":"The different ways to show the same function: an equation, a table, a graph, or a verbal description."},{"term":"square root function","def":"The parent function f(x) = √x."}]},{"unit":2,"title":"Absolute Value Functions, Equations, and Inequalities","terms":[{"term":"continuous function","def":"The graph is unbroken — you could trace it without ever lifting your pencil."},{"term":"discrete function","def":"The graph is made of separate, disconnected points — nothing connects them."},{"term":"domain","def":"The set of all possible input values (x-values) a function can use."},{"term":"extraneous solution","def":"A value the algebra produces that does NOT actually satisfy the original equation — happens here because splitting |A| = k into two cases can create a solution where the \"inside\" expression has the wrong sign for that case."},{"term":"inequality notation","def":"Writing domain or range using \u003c, ≤, \u003e, or ≥ instead of interval or set notation, e.g. x ≥ 0."},{"term":"interval notation","def":"Writing a range of values using brackets/parentheses, e.g. [0, ∞) — bracket if included, parenthesis if excluded, ∞ always gets a parenthesis."},{"term":"range","def":"The set of all possible output values (y-values) a function can produce."},{"term":"reflectional symmetry","def":"The graph can be folded across a line and land exactly on itself — f(x) = |x| folds across the y-axis."},{"term":"relative maximum","def":"The largest y-value a graph reaches on a given interval — not necessarily the highest point on the whole graph. f(x) = |x| has none; it increases without bound in both directions."},{"term":"relative minimum","def":"The smallest y-value a graph reaches on a given interval. For f(x) = |x|, that\u0027s 0, at the vertex."},{"term":"set notation","def":"Writing a domain or range using braces and a \"such that\" bar, e.g. {x | x ≥ 0}."},{"term":"x-intercept(s)","def":"The point(s) where a graph crosses the x-axis. There, y = 0."},{"term":"y-intercept(s)","def":"The point where a graph crosses the y-axis. There, x = 0."},{"term":"zeros","def":"The x-value(s) that make a function equal 0 — the same locations as the x-intercepts."},{"term":"absolute value","def":"The distance a number is from 0 on the number line — always non-negative (≥ 0)."},{"term":"function notation","def":"Writing a function as f(x) instead of y — read \"f of x.\""},{"term":"representation of solutions","def":"Stating a solution in more than one equivalent way — as specific values, a compound inequality, interval notation, or a graph."},{"term":"restricted domain","def":"A domain narrowed from all real numbers to fit a real-world situation, e.g. Day 3\u0027s roofline model only makes sense over the stretch of roof it\u0027s describing."},{"term":"simplify","def":"Rewrite an expression in a shorter, equivalent form."},{"term":"stretch/compress","def":"A vertical or horizontal change that makes a graph narrower (stretch) or wider (compress) without moving it."},{"term":"transformation","def":"A change to a parent function\u0027s graph: a stretch, compression, reflection, or shift."},{"term":"translate","def":"To shift a graph horizontally and/or vertically without changing its shape."},{"term":"vertex","def":"The point where the two straight-line pieces of f(x) = |x| meet — for the parent function, (0, 0)."},{"term":"vertical/horizontal shift","def":"f(x) + d moves the graph up/down, same direction as the sign of d. f(x − c) moves it left/right, opposite the sign of c."}]},{"unit":3,"title":"Systems of Linear Equations and Inequalities","terms":[{"term":"Gaussian elimination","def":"Solving a system using row operations — swapping two rows, scaling a row, or adding a multiple of one row to another — to reach row-echelon form, then back-substituting to find each variable."},{"term":"standard form for systems of equations","def":"Writing every equation in a system with its variables in the same alphabetical order on the left and the constant alone on the right, e.g. x + 2y + 3z = 40.5 — keeps the system lined up correctly for elimination or matrix methods."},{"term":"augmented matrix","def":"A matrix that combines a system\u0027s coefficients and constants into one grid, written [A | C] — solved by row-reducing it to rref."},{"term":"coinciding lines","def":"Two equations that graph as the exact same line — every point on one is a solution to both, giving infinitely many solutions."},{"term":"column in a matrix","def":"A vertical line of numbers in a matrix, read top to bottom."},{"term":"consistent lines","def":"A system that has at least one solution — its lines either intersect once (independent) or coincide (dependent)."},{"term":"dependent lines","def":"Two equations whose lines coincide — really the same line written two ways, so every point on it is a solution."},{"term":"dimension of a matrix","def":"A matrix\u0027s size, written rows × columns — e.g. a matrix with 2 rows and 3 columns is 2×3."},{"term":"feasible region","def":"The region where every inequality in a system is satisfied at once — the shaded overlap of all the individual solution sets. Linear programming looks for a max/min inside it."},{"term":"identity matrix","def":"A square matrix with 1\u0027s down the main diagonal and 0\u0027s everywhere else — multiplying any matrix by it leaves that matrix unchanged."},{"term":"inconsistent lines","def":"A system with no solution — its lines are parallel and never intersect."},{"term":"independent lines","def":"Two equations whose lines intersect at exactly one point — that point is the system\u0027s one solution."},{"term":"infinite number of solutions","def":"Every point that satisfies one equation also satisfies the rest — happens when the equations describe the same line or plane. In row-echelon form, it shows up as a row of all zeros equal to 0 (0 = 0)."},{"term":"intersection of lines","def":"The point (or points) where two or more lines cross — a shared solution to both equations."},{"term":"inverse matrix","def":"A matrix that, multiplied by the original, gives the identity matrix — written [A]⁻¹. Used to solve a system as [A]⁻¹ · [C]."},{"term":"linear equation in three variables","def":"An equation with three variables (usually x, y, z), each to the first power, e.g. 4x + 3y + 2z = 57 — graphs as a plane, not a line."},{"term":"linear programming","def":"Using a system of linear inequalities\u0027 feasible region to find the maximum or minimum value of an objective function, by testing that function at each vertex of the region."},{"term":"matrix","def":"A rectangular grid of numbers, arranged in rows and columns."},{"term":"maximize","def":"Find the largest possible value of the objective function within the feasible region — in linear programming, checked at the region\u0027s vertices."},{"term":"minimize","def":"Find the smallest possible value of the objective function within the feasible region — in linear programming, checked at the region\u0027s vertices."},{"term":"no solutions","def":"No point satisfies every equation or inequality in the system at once — for lines, this means they\u0027re parallel. In row-echelon form, it shows up as a row of all zeros equal to a nonzero constant (0 = 1)."},{"term":"ordered triple","def":"A solution to a three-variable system, written (x, y, z) — one value for each variable."},{"term":"reduced row echelon form (rref)","def":"The simplest form an augmented matrix can be row-reduced to — 1\u0027s down the main diagonal, 0\u0027s everywhere else in that block — so each row reads directly as one variable\u0027s value."},{"term":"row of a matrix","def":"A horizontal line of numbers in a matrix, read left to right."},{"term":"vertices of a region","def":"The corner points of a feasible region — in linear programming, the only points that ever need to be checked to find a maximum or minimum."}]},{"unit":4,"title":"Expressions, Factoring, and Equations with Rational Exponents","terms":[{"term":"binomial","def":"A polynomial with exactly two terms, e.g. 4x + 5."},{"term":"monomial","def":"A single term made of a number, a variable, or their product, e.g. 3x²y — no addition or subtraction inside it."},{"term":"polynomial expression","def":"An expression built from monomials added or subtracted together, e.g. 2x² + 9x + 10."},{"term":"radical expression","def":"An expression containing a root symbol (√, ∛, etc.), e.g. √(8x³y⁴)."},{"term":"trinomial","def":"A polynomial with exactly three terms, e.g. x² + 5x − 24."},{"term":"coefficient","def":"The number multiplied by a variable in a term, e.g. the 4 in 4x²."},{"term":"constant","def":"A term with no variable — its value never changes, e.g. the 10 in 2x² + 9x + 10."},{"term":"degree of a monomial","def":"The sum of the exponents on all of a monomial\u0027s variables, e.g. 3x²y has degree 3 (2 + 1)."},{"term":"degree of a polynomial","def":"The highest degree of any single term in the polynomial."},{"term":"exponential expression","def":"An expression with a variable or another expression raised to a power, e.g. x^(1/3)."},{"term":"factoring","def":"Rewriting an expression as a product of simpler expressions that multiply back to the original."},{"term":"greatest common factor (GCF)","def":"The largest expression that divides evenly out of every term — pulled out first when factoring, e.g. 4xy from 12x²y² − 16x²y + 12xy²."},{"term":"index number","def":"The small number on a root symbol showing which root to take, e.g. the 3 in ∛x (cube root). No index shown means index 2 (square root)."},{"term":"laws of exponents","def":"The rules for combining exponents when multiplying, dividing, or raising powers to powers — e.g. multiplying same-base powers adds their exponents."},{"term":"properties of algebra","def":"The rules (commutative, associative, distributive, etc.) that justify each step when rewriting an expression or solving an equation."}]},{"unit":5,"title":"Quadratic Relations, Equations, and Inequalities","terms":[{"term":"complex conjugates","def":"A pair of complex numbers a + bi and a − bi that differ only in the sign of the imaginary part — their sum and product are always real numbers."},{"term":"complex number","def":"A number written a + bi, where a is the real part and b is the imaginary part (i = √−1)."},{"term":"directrix","def":"A fixed line used to define a parabola — every point on the parabola is the same distance from the directrix as it is from the focus."},{"term":"|p|","def":"The distance from a parabola\u0027s vertex to its focus (and to its directrix) — used in the conic form (x−h)² = 4p(y−k), where a = 1/(4p)."},{"term":"focus","def":"A fixed point used to define a parabola — every point on the parabola is the same distance from the focus as it is from the directrix."},{"term":"imaginary number","def":"A number that includes i = √−1, showing up whenever a square root of a negative number appears, e.g. √−121 = 11i."},{"term":"parabola","def":"The U-shaped graph of a quadratic function — the set of all points equidistant from a focus and a directrix."},{"term":"x-intercept(s)","def":"The point(s) where a graph crosses the x-axis. There, y = 0."},{"term":"zeros","def":"The x-value(s) that make a function equal 0 — the same locations as the x-intercepts."},{"term":"axis of symmetry","def":"The vertical line through a parabola\u0027s vertex that splits it into two mirror-image halves — x = h in vertex form, x = −b/2a in standard form."},{"term":"completing the square","def":"Rewriting ax² + bx + c as a(x−h)² + k by building a perfect-square trinomial — the method used to go from standard form to vertex form."},{"term":"discriminant","def":"The value b² − 4ac inside the quadratic formula — its sign, and whether it\u0027s a perfect square, tells you how many real or complex roots a quadratic has."},{"term":"factoring","def":"Rewriting an expression as a product of simpler expressions that multiply back to the original."},{"term":"Fundamental Theorem of Algebra","def":"Every polynomial of degree n has exactly n roots, counting complex roots and repeats."},{"term":"Gaussian method","def":"Gaussian elimination — using row operations to reduce a system to row-echelon form, then back-substituting. Reused here (from Unit 03) to solve the 3x3 system that comes from writing a quadratic through three points."},{"term":"horizontal shift","def":"f(x−c) moves the graph left/right, opposite the sign of c."},{"term":"inverse matrix","def":"A matrix that, multiplied by the original, gives the identity matrix — written [A]⁻¹. Reused here (from Unit 03) to solve for a, b, c when writing a quadratic through three points."},{"term":"locus of points","def":"A set of points that all satisfy the same rule or distance condition — a parabola is the locus of points equidistant from a focus and a directrix."},{"term":"maximum","def":"The single highest y-value a graph reaches — for a downward-opening parabola (a\u003c0), that\u0027s the vertex."},{"term":"minimum","def":"The single lowest y-value a graph reaches — for an upward-opening parabola (a\u003e0), that\u0027s the vertex."},{"term":"operations of complex numbers","def":"Adding, subtracting, and multiplying complex numbers — combine real parts with real parts and imaginary parts with imaginary parts, and remember i² = −1 when multiplying."},{"term":"quadratic equation","def":"An equation that can be written ax² + bx + c = 0 (a ≠ 0)."},{"term":"quadratic formula","def":"x = (−b ± √(b² − 4ac)) / 2a — solves any quadratic equation ax² + bx + c = 0."},{"term":"quadratic function","def":"A function of the form f(x) = ax² + bx + c (a ≠ 0) — the parent function is f(x) = x²."},{"term":"quadratic inequality","def":"An inequality involving a quadratic expression, e.g. x² + 3x \u003c 10 — solved by comparing to zero and testing intervals, or by graphing."},{"term":"quadratic regression","def":"Using technology to fit the best quadratic model, f(x) = ax² + bx + c, to a set of data points."},{"term":"real numbers","def":"Every number on the number line — includes rationals and irrationals, but not imaginary numbers."},{"term":"roots","def":"The solutions to an equation set equal to 0 — for a quadratic, the same values as the zeros/x-intercepts (or complex, if the parabola never crosses the x-axis)."},{"term":"rref","def":"Reduced row echelon form — the simplest form a matrix can be row-reduced to, so each row reads directly as one variable\u0027s value. Reused here (from Unit 03) to solve for a quadratic\u0027s a, b, c."},{"term":"solutions","def":"The value(s) that make an equation true."},{"term":"standard form, f(x) = ax^2 + bx + c","def":"Writing a quadratic with the squared term first, then the linear term, then the constant — reveals the y-intercept (c) directly."},{"term":"substitution method","def":"Solving a system by solving one equation for a variable and substituting that expression into the other equation(s)."},{"term":"symmetric point","def":"A parabola\u0027s mirror-image partner of a given point, reflected across the axis of symmetry — same y-value, same distance from the axis on the other side."},{"term":"transformation","def":"A change to a parent function\u0027s graph: a stretch, compression, reflection, or shift."},{"term":"vertex","def":"The turning point of a parabola — its minimum (opens up) or maximum (opens down)."},{"term":"vertex form, f(x) = a(x - h)^2 + k","def":"Writing a quadratic so its vertex (h, k) can be read directly off the equation."},{"term":"vertical compression","def":"0 \u003c |a| \u003c 1 in af(x) — pulls the graph toward the x-axis, making it look flatter/wider."},{"term":"vertical shift","def":"f(x) + d moves the graph up/down — up if d \u003e 0, down if d \u003c 0."},{"term":"vertical stretch","def":"|a| \u003e 1 in af(x) — pulls the graph away from the x-axis, making it look narrower/steeper."}]},{"unit":6,"title":"Square Root Functions and Equations","terms":[{"term":"composition of functions","def":"Putting one function inside another and evaluating: f(g(x)), read \"f of g of x.\" Work from the inside out."},{"term":"continuous function","def":"The graph is unbroken — you could trace it without ever lifting your pencil."},{"term":"discrete function","def":"The graph is made of separate, disconnected points — nothing connects them."},{"term":"domain","def":"The set of all possible input values (x-values) a function can use."},{"term":"extraneous solution","def":"A value the algebra produces that does NOT actually satisfy the original equation — happens with square root equations because squaring both sides isn\u0027t reversible, e.g. solving √(x+5)−3=x gives x=−1 (valid) and x=−4 (extraneous)."},{"term":"inequality notation","def":"Writing domain or range using \u003c, ≤, \u003e, or ≥ instead of interval or set notation, e.g. x ≥ 0."},{"term":"interval notation","def":"Writing a range of values using brackets/parentheses, e.g. [0, ∞) — bracket if included, parenthesis if excluded, ∞ always gets a parenthesis."},{"term":"inverse of a function","def":"The function that undoes the original — written f⁻¹(x). For f(x) = x² restricted to x ≥ 0, the inverse is f⁻¹(x) = √x."},{"term":"parent functions","def":"The simplest, unmodified form of a function family — f(x) = √x for the square root family."},{"term":"range","def":"The set of all possible output values (y-values) a function can produce."},{"term":"set notation","def":"Writing a domain or range using braces and a \"such that\" bar, e.g. {x | x ≥ 0}."},{"term":"x-intercept(s)","def":"The point(s) where a graph crosses the x-axis. There, y = 0."},{"term":"y-intercept(s)","def":"The point where a graph crosses the y-axis. There, x = 0."},{"term":"zeros","def":"The x-value(s) that make a function equal 0 — the same locations as the x-intercepts."},{"term":"complex numbers","def":"Numbers written a + bi, where i = √−1 — show up here when a quadratic under a square root has no real solution."},{"term":"compress","def":"A transformation that pulls a graph toward an axis, making it narrower (vertical) or shrinking it horizontally toward the axis (horizontal)."},{"term":"endpoint","def":"The point where a graph\u0027s domain begins — f(x) = √x starts at (0, 0), since there\u0027s nothing to the left of it."},{"term":"evaluate","def":"Substitute a value in for the variable and simplify to find the output."},{"term":"function notation","def":"Writing a function as f(x) instead of y — read \"f of x.\""},{"term":"horizontal shift","def":"f(x−c) moves the graph left/right, opposite the sign of c."},{"term":"quadratic","def":"Involving a squared variable — f(x) = √x is the inverse of the quadratic parent function f(x) = x² (restricted to x ≥ 0)."},{"term":"radical","def":"An expression written with a root symbol (√), such as √x."},{"term":"rational exponent","def":"A fractional exponent, e.g. x^(1/2) — equivalent to a radical: x^(1/2) = √x."},{"term":"reflection","def":"A transformation that flips a graph over an axis — a \u003c 0 in af(x) flips over the x-axis; b \u003c 0 in f(bx) flips over the y-axis."},{"term":"restricted domain","def":"A domain narrowed from all real numbers — needed here because f(x) = x² isn\u0027t one-to-one; restricting it to x ≥ 0 (or x ≤ 0) makes its inverse, √x, a function too."},{"term":"simplify","def":"Rewrite an expression in a shorter, equivalent form."},{"term":"square root equation","def":"An equation with a variable inside a square root, e.g. √(x−3) + 5 = 9 — solved by isolating the radical and squaring both sides."},{"term":"square root function","def":"The parent function f(x) = √x — the inverse of f(x) = x² (restricted to x ≥ 0)."},{"term":"stretch","def":"A transformation that pulls a graph away from an axis, making it wider (vertical) or steeper (horizontal)."},{"term":"symmetry over y = x","def":"A function and its inverse are always mirror images of each other across the line y = x — swap the x\u0027s and y\u0027s, and you\u0027ve reflected across this line."},{"term":"transformation","def":"A change to a parent function\u0027s graph: a stretch, compression, reflection, or shift."},{"term":"translate","def":"To shift a graph horizontally and/or vertically without changing its shape."},{"term":"vertex","def":"The point where a graph changes direction — for f(x) = √x, its one endpoint, (0, 0), acts like a vertex since the curve only extends one way from there."},{"term":"vertical shift","def":"f(x) + d moves the graph up/down — up if d \u003e 0, down if d \u003c 0."}]},{"unit":7,"title":"Cubic and Cube Root Functions and Equations","terms":[{"term":"composition of functions","def":"Putting one function inside another and evaluating: f(g(x)), read \"f of g of x.\" Work from the inside out."},{"term":"continuous function","def":"The graph is unbroken — you could trace it without ever lifting your pencil."},{"term":"discrete function","def":"The graph is made of separate, disconnected points — nothing connects them."},{"term":"domain","def":"The set of all possible input values (x-values) a function can use."},{"term":"inequality notation","def":"Writing domain or range using \u003c, ≤, \u003e, or ≥ instead of interval or set notation, e.g. x ≥ 0."},{"term":"interval notation","def":"Writing a range of values using brackets/parentheses, e.g. [0, ∞) — bracket if included, parenthesis if excluded, ∞ always gets a parenthesis."},{"term":"inverse of a function","def":"The function that undoes the original — written f⁻¹(x). For f(x) = x³, the inverse is f⁻¹(x) = ∛x."},{"term":"range","def":"The set of all possible output values (y-values) a function can produce."},{"term":"reflectional symmetry","def":"The graph can be folded across a line and land exactly on itself."},{"term":"relative maximum","def":"The largest y-value a graph reaches on a given interval — not necessarily the highest point on the whole graph."},{"term":"relative minimum","def":"The smallest y-value a graph reaches on a given interval."},{"term":"rotational symmetry","def":"The graph looks the same after being rotated some amount around a point — f(x) = x³ and f(x) = ∛x both have 180° rotational symmetry about the origin."},{"term":"set notation","def":"Writing a domain or range using braces and a \"such that\" bar, e.g. {x | x ≥ 0}."},{"term":"x-intercept(s)","def":"The point(s) where a graph crosses the x-axis. There, y = 0."},{"term":"y-intercept(s)","def":"The point where a graph crosses the y-axis. There, x = 0."},{"term":"zeros","def":"The x-value(s) that make a function equal 0 — the same locations as the x-intercepts."},{"term":"cube root equation","def":"An equation with a variable inside a cube root, e.g. ∛x = 2 — cube both sides to solve (no extraneous-solution risk, unlike square root equations, since cubing works fine for negatives too)."},{"term":"cube root function","def":"The parent function f(x) = ∛x — the inverse of f(x) = x³."},{"term":"cubic function","def":"The parent function f(x) = x³."},{"term":"extraneous solution","def":"A value the algebra produces that does NOT actually satisfy the original equation."},{"term":"horizontal compression","def":"|b| \u003e 1 in f(bx) — squeezes the graph toward the y-axis."},{"term":"horizontal shift","def":"f(x−c) moves the graph left/right, opposite the sign of c."},{"term":"horizontal stretch","def":"0 \u003c |b| \u003c 1 in f(bx) — pulls the graph away from the y-axis."},{"term":"parameter change","def":"Changing one of a, b, c, d in af(bx−c)+d and tracking how that single change affects the graph."},{"term":"properties of exponents","def":"The rules for combining exponents when multiplying, dividing, or raising powers to powers."},{"term":"rational exponents","def":"Fractional exponents, e.g. x^(1/3) — equivalent to a radical: x^(1/3) = ∛x."},{"term":"root","def":"A solution to an equation set equal to 0 — the same as a zero."},{"term":"solution","def":"A value that makes an equation true."},{"term":"vertical compression","def":"0 \u003c |a| \u003c 1 in af(x) — pulls the graph toward the x-axis."},{"term":"vertical shift","def":"f(x) + d moves the graph up/down — up if d \u003e 0, down if d \u003c 0."},{"term":"vertical stretch","def":"|a| \u003e 1 in af(x) — pulls the graph away from the x-axis."}]},{"unit":8,"title":"Rational Functions and Equations","terms":[{"term":"asymptote","def":"A line a graph gets closer and closer to but never actually crosses (a horizontal or oblique asymptote may still be crossed elsewhere on the graph)."},{"term":"asymptotic behavior","def":"How a graph behaves near a value it gets closer and closer to but never reaches."},{"term":"continuous function","def":"The graph is unbroken — you could trace it without ever lifting your pencil."},{"term":"direct variation","def":"A relationship y = kx — as x increases, y increases at a constant rate. k is the constant of variation."},{"term":"discontinuity","def":"A break in a graph — a point or interval where the function isn\u0027t connected or isn\u0027t defined."},{"term":"discrete function","def":"The graph is made of separate, disconnected points — nothing connects them."},{"term":"domain","def":"The set of all possible input values (x-values) a function can use."},{"term":"horizontal asymptote","def":"A horizontal line a graph\u0027s y-values get closer and closer to as x gets very large or very small. For a rational function: y = 0 if the numerator\u0027s degree is less than the denominator\u0027s; y = the ratio of leading coefficients if the degrees are equal."},{"term":"inequality notation","def":"Writing domain or range using \u003c, ≤, \u003e, or ≥ instead of interval or set notation, e.g. x ≥ 0."},{"term":"interval notation","def":"Writing a range of values using brackets/parentheses, e.g. [0, ∞) — bracket if included, parenthesis if excluded, ∞ always gets a parenthesis."},{"term":"inverse variation","def":"A relationship y = k/x — as x increases, y decreases. k is the constant of variation."},{"term":"point (removable) discontinuity","def":"A single missing point (\"hole\") in a graph, where a factor cancels between a rational function\u0027s numerator and denominator."},{"term":"range","def":"The set of all possible output values (y-values) a function can produce."},{"term":"rotational symmetry","def":"The graph looks the same after being rotated some amount around a point — f(x) = 1/x has 180° rotational symmetry about the origin."},{"term":"set notation","def":"Writing a domain or range using braces and a \"such that\" bar, e.g. {x | x ≥ 0}."},{"term":"vertical asymptote","def":"A vertical line the graph gets closer and closer to but never crosses — for a rational function, where the denominator equals 0 after any cancellation."},{"term":"x-intercept(s)","def":"The point(s) where a graph crosses the x-axis. There, y = 0."},{"term":"y-intercept(s)","def":"The point where a graph crosses the y-axis. There, x = 0."},{"term":"zeros","def":"The x-value(s) that make a function equal 0 — the same locations as the x-intercepts."},{"term":"constant of variation","def":"The k in a direct (y = kx) or inverse (y = k/x) variation equation."},{"term":"extraneous solution","def":"A value the algebra produces that does NOT actually satisfy the original equation — for a rational equation, this happens when a solution makes one of the original denominators equal 0."},{"term":"horizontal compression","def":"|b| \u003e 1 in f(bx) — squeezes the graph toward the y-axis."},{"term":"horizontal shift","def":"f(x−c) moves the graph left/right, opposite the sign of c."},{"term":"horizontal stretch","def":"0 \u003c |b| \u003c 1 in f(bx) — pulls the graph away from the y-axis."},{"term":"least common denominator","def":"The smallest expression that all denominators in a sum or difference of rational expressions divide into evenly — used to combine them into one fraction."},{"term":"parameter change","def":"Changing one of a, b, c, d in af(bx−c)+d and tracking how that single change affects the graph."},{"term":"parent functions","def":"The simplest, unmodified form of a function family — f(x) = 1/x for the rational family."},{"term":"rational equation","def":"An equation that includes at least one rational expression — solved by graphing, cross-multiplying, or multiplying through by the LCD, then checking for extraneous solutions."},{"term":"rational exponents","def":"Fractional exponents, e.g. x^(1/2)."},{"term":"rational function","def":"The parent function f(x) = 1/x."},{"term":"reciprocal of x","def":"1/x — the expression that gives the rational parent function its shape."},{"term":"variation","def":"A relationship where one variable changes in a predictable way as another changes — direct (y = kx) or inverse (y = k/x)."},{"term":"vertical compression","def":"0 \u003c |a| \u003c 1 in af(x) — pulls the graph toward the x-axis."},{"term":"vertical shift","def":"f(x) + d moves the graph up/down — up if d \u003e 0, down if d \u003c 0."},{"term":"vertical stretch","def":"|a| \u003e 1 in af(x) — pulls the graph away from the x-axis."}]},{"unit":9,"title":"Exponential Functions and Equations","terms":[{"term":"asymptotic behavior","def":"How a graph behaves near a value it gets closer and closer to but never reaches."},{"term":"continuous function","def":"The graph is unbroken — you could trace it without ever lifting your pencil."},{"term":"domain","def":"The set of all possible input values (x-values) a function can use."},{"term":"exponential decay","def":"A function that decreases by a constant percentage each period — f(x) = ab^x with 0 \u003c b \u003c 1."},{"term":"exponential growth","def":"A function that increases by a constant percentage each period — f(x) = ab^x with b \u003e 1."},{"term":"horizontal asymptote","def":"A horizontal line that a graph\u0027s y-values get closer and closer to as x gets very large or very small — for f(x) = ab^x + d, that\u0027s y = d."},{"term":"inequality notation","def":"Writing domain or range using \u003c, ≤, \u003e, or ≥ instead of interval or set notation, e.g. x ≥ 0."},{"term":"interval notation","def":"Writing a range of values using brackets/parentheses, e.g. [0, ∞) — bracket if included, parenthesis if excluded, ∞ always gets a parenthesis."},{"term":"range","def":"The set of all possible output values (y-values) a function can produce."},{"term":"recursive notation","def":"Defining a sequence by a starting value and a rule that builds each next term from the one before it, e.g. a₁ = 5, aₙ = 4aₙ₋₁."},{"term":"set notation","def":"Writing a domain or range using braces and a \"such that\" bar, e.g. {x | x ≥ 0}."},{"term":"x-intercept(s)","def":"The point(s) where a graph crosses the x-axis. There, y = 0."},{"term":"y-intercept(s)","def":"The point where a graph crosses the y-axis. There, x = 0."},{"term":"zeros","def":"The x-value(s) that make a function equal 0 — the same locations as the x-intercepts."},{"term":"base","def":"The b in f(x) = b^x — determines growth (b \u003e 1) or decay (0 \u003c b \u003c 1)."},{"term":"decreasing","def":"As x increases, y gets smaller — the graph falls from left to right over that interval."},{"term":"depreciate","def":"To lose value over time — modeled by exponential decay, e.g. a car\u0027s value dropping by a fixed percent each year."},{"term":"evaluate","def":"Substitute a value in for the variable and simplify to find the output."},{"term":"exponent","def":"The power a base is raised to, e.g. the x in b^x."},{"term":"exponential regression","def":"Using technology to fit the best exponential model, f(x) = ab^x, to a set of data points."},{"term":"function notation","def":"Writing a function as f(x) instead of y — read \"f of x.\""},{"term":"horizontal compression","def":"|b| \u003e 1 in f(bx) — squeezes the graph toward the y-axis."},{"term":"horizontal shift","def":"f(x−c) moves the graph left/right, opposite the sign of c."},{"term":"horizontal stretch","def":"0 \u003c |b| \u003c 1 in f(bx) — pulls the graph away from the y-axis."},{"term":"increasing","def":"As x increases, y also gets bigger — the graph rises from left to right over that interval."},{"term":"interest","def":"Money earned or owed as a percentage of an amount, compounding over time — a real-world example of exponential growth."},{"term":"parameter change","def":"Changing one of a, c, d in af(x−c)+d and tracking how that single change affects the graph."},{"term":"parent function","def":"The simplest, unmodified form of a function family — f(x) = b^x for the exponential family."},{"term":"vertical compression","def":"0 \u003c |a| \u003c 1 in af(x) — pulls the graph toward the x-axis."},{"term":"vertical shift","def":"f(x) + d moves the graph up/down — up if d \u003e 0, down if d \u003c 0."},{"term":"vertical stretch","def":"|a| \u003e 1 in af(x) — pulls the graph away from the x-axis."}]},{"unit":10,"title":"Exponential and Logarithmic Functions and Equations","terms":[{"term":"asymptotic behavior","def":"How a graph behaves near a value it gets closer and closer to but never reaches."},{"term":"composition of functions","def":"Putting one function inside another and evaluating: f(g(x)), read \"f of g of x.\" Work from the inside out."},{"term":"continuous function","def":"The graph is unbroken — you could trace it without ever lifting your pencil."},{"term":"discrete function","def":"The graph is made of separate, disconnected points — nothing connects them."},{"term":"domain","def":"The set of all possible input values (x-values) a function can use."},{"term":"exponential decay","def":"A function that decreases by a constant percentage each period — f(x) = ab^x with 0 \u003c b \u003c 1."},{"term":"exponential growth","def":"A function that increases by a constant percentage each period — f(x) = ab^x with b \u003e 1."},{"term":"horizontal asymptote","def":"A horizontal line that a graph\u0027s y-values get closer and closer to as x gets very large or very small — for an exponential function f(x) = ab^x + d, that\u0027s y = d."},{"term":"inequality notation","def":"Writing domain or range using \u003c, ≤, \u003e, or ≥ instead of interval or set notation, e.g. x ≥ 0."},{"term":"interval notation","def":"Writing a range of values using brackets/parentheses, e.g. [0, ∞) — bracket if included, parenthesis if excluded, ∞ always gets a parenthesis."},{"term":"inverse of a function","def":"The function that undoes the original — written f⁻¹(x). f(x) = b^x and f(x) = log_b(x) are inverses of each other."},{"term":"range","def":"The set of all possible output values (y-values) a function can produce."},{"term":"set notation","def":"Writing a domain or range using braces and a \"such that\" bar, e.g. {x | x ≥ 0}."},{"term":"vertical asymptote","def":"A vertical line the graph gets closer and closer to but never crosses — for f(x) = log_b(x), that\u0027s where its argument would hit 0."},{"term":"x-intercept(s)","def":"The point(s) where a graph crosses the x-axis. There, y = 0."},{"term":"y-intercept(s)","def":"The point where a graph crosses the y-axis. There, x = 0."},{"term":"zeros","def":"The x-value(s) that make a function equal 0 — the same locations as the x-intercepts."},{"term":"decreasing","def":"As x increases, y gets smaller — the graph falls from left to right over that interval."},{"term":"dependent","def":"The output of a function — it depends on what you put in. Goes on the y-axis."},{"term":"evaluate","def":"Substitute a value in for the variable and simplify to find the output."},{"term":"exponent","def":"The power a base is raised to, e.g. the x in b^x."},{"term":"exponential regression","def":"Using technology to fit the best exponential model, f(x) = ab^x, to a set of data points."},{"term":"function notation","def":"Writing a function as f(x) instead of y — read \"f of x.\""},{"term":"horizontal compression","def":"|b| \u003e 1 in f(bx) — squeezes the graph toward the y-axis."},{"term":"horizontal shift","def":"f(x−c) moves the graph left/right, opposite the sign of c."},{"term":"horizontal stretch","def":"0 \u003c |b| \u003c 1 in f(bx) — pulls the graph away from the y-axis."},{"term":"increasing","def":"As x increases, y also gets bigger — the graph rises from left to right over that interval."},{"term":"independent","def":"The input of a function — the value you choose. Goes on the x-axis."},{"term":"logarithmic regression","def":"Using technology to fit the best logarithmic model to a set of data points."},{"term":"parameter change","def":"Changing one of a, c, d in af(x−c)+d and tracking how that single change affects the graph."},{"term":"parent function","def":"The simplest, unmodified form of a function family — f(x) = log_b(x) for the logarithmic family."},{"term":"reflection","def":"A transformation that flips a graph over an axis — a \u003c 0 in af(x) flips over the x-axis."},{"term":"vertical compression","def":"0 \u003c |a| \u003c 1 in af(x) — pulls the graph toward the x-axis."},{"term":"vertical shift","def":"f(x) + d moves the graph up/down — up if d \u003e 0, down if d \u003c 0."},{"term":"vertical stretch","def":"|a| \u003e 1 in af(x) — pulls the graph away from the x-axis."},{"term":"y = x line","def":"The line functions and their inverses are mirror images across — f(x) = b^x and f(x) = log_b(x) reflect over this line."}]},{"unit":11,"title":"Linear, Quadratic, and Exponential Data Models","terms":[{"term":"coefficient of determination (r²-value)","def":"A number from 0 to 1 showing how well a regression model fits the data, for any model type — closer to 1 means a better fit."},{"term":"correlation coefficient (r-value)","def":"A number from −1 to 1 showing how strong a LINEAR relationship is in the data — only valid for linear models. Closer to ±1 means a stronger fit."},{"term":"regression equation","def":"The equation technology produces to model a data set as closely as possible, e.g. f(x) = 6.53(1.03)^x."},{"term":"common ratio","def":"The constant ratio between consecutive y-values in a data set — a signal the data fits an exponential model."},{"term":"exponential","def":"Growing or shrinking by a constant ratio each step — f(x) = ab^x."},{"term":"first differences","def":"The differences between consecutive y-values in a data set — constant first differences signal a linear model."},{"term":"linear","def":"Changing at a constant rate — f(x) = mx + b."},{"term":"quadratic","def":"Changing so that the rate of change itself changes at a constant rate — f(x) = ax² + bx + c; signaled by constant second differences."},{"term":"rate of change","def":"How much y changes for each unit increase in x."},{"term":"regression","def":"Using technology to find the equation that best fits a set of data points."},{"term":"second differences","def":"The differences between consecutive first differences — constant second differences signal a quadratic model."},{"term":"sequential data","def":"Data given in order, typically as evenly spaced x-values (like consecutive years) with paired y-values — this is what lets you check first/second differences or a common ratio."}]},{"unit":12,"title":"Making Connections (spiral review)","terms":[{"term":"asymptote","def":"A line a graph gets closer and closer to but never actually crosses (a horizontal or oblique asymptote may still be crossed elsewhere on the graph)."},{"term":"asymptotic behavior","def":"How a graph behaves near a value it gets closer and closer to but never reaches."},{"term":"complex conjugates","def":"A pair of complex numbers a + bi and a − bi that differ only in the sign of the imaginary part — their sum and product are always real numbers."},{"term":"complex number","def":"A number written a + bi, where a is the real part and b is the imaginary part (i = √−1)."},{"term":"continuous function","def":"The graph is unbroken — you could trace it without ever lifting your pencil."},{"term":"direct variation","def":"A relationship y = kx — as x increases, y increases at a constant rate."},{"term":"directrix","def":"A fixed line used to define a parabola — every point on the parabola is the same distance from the directrix as it is from the focus."},{"term":"discontinuity","def":"A break in a graph — a point or interval where the function isn\u0027t connected or isn\u0027t defined."},{"term":"discrete function","def":"The graph is made of separate, disconnected points — nothing connects them."},{"term":"domain","def":"The set of all possible input values (x-values) a function can use."},{"term":"extraneous solution","def":"A value the algebra produces that does NOT actually satisfy the original equation — can happen whenever a solving step isn\u0027t reversible: splitting an absolute value into cases, squaring a square-root equation, or clearing a rational equation\u0027s denominators."},{"term":"focus","def":"A fixed point used to define a parabola — every point on the parabola is the same distance from the focus as it is from the directrix."},{"term":"Gaussian elimination","def":"Solving a system using row operations — swapping two rows, scaling a row, or adding a multiple of one row to another — to reach row-echelon form, then back-substituting."},{"term":"horizontal asymptote","def":"A horizontal line that a graph\u0027s y-values get closer and closer to as x gets very large or very small."},{"term":"imaginary number","def":"A number that includes i = √−1, showing up whenever a square root of a negative number appears."},{"term":"inequality notation","def":"Writing domain or range using \u003c, ≤, \u003e, or ≥ instead of interval or set notation, e.g. x ≥ 0."},{"term":"interval notation","def":"Writing a range of values using brackets/parentheses, e.g. [0, ∞) — bracket if included, parenthesis if excluded, ∞ always gets a parenthesis."},{"term":"inverse variation","def":"A relationship y = k/x — as x increases, y decreases."},{"term":"parabola","def":"The U-shaped graph of a quadratic function — the set of all points equidistant from a focus and a directrix."},{"term":"point (removable) discontinuity","def":"A single missing point (\"hole\") in a graph, where a factor cancels between a rational function\u0027s numerator and denominator."},{"term":"range","def":"The set of all possible output values (y-values) a function can produce."},{"term":"reflectional symmetry","def":"The graph can be folded across a line and land exactly on itself."},{"term":"relative maximum","def":"The largest y-value a graph reaches on a given interval — not necessarily the highest point on the whole graph."},{"term":"relative minimum","def":"The smallest y-value a graph reaches on a given interval."},{"term":"rotational symmetry","def":"The graph looks the same after being rotated some amount around a point."},{"term":"set notation","def":"Writing a domain or range using braces and a \"such that\" bar, e.g. {x | x ≥ 0}."},{"term":"vertical asymptote","def":"A vertical line the graph gets closer and closer to but never crosses."},{"term":"x-intercept(s)","def":"The point(s) where a graph crosses the x-axis. There, y = 0."},{"term":"y-intercept(s)","def":"The point where a graph crosses the y-axis. There, x = 0."},{"term":"zeros","def":"The x-value(s) that make a function equal 0 — the same locations as the x-intercepts."},{"term":"absolute value function","def":"The parent function f(x) = |x|."},{"term":"correlation value","def":"A number describing how well a model fits data — r for linear fit strength, r² for any model type\u0027s fit quality."},{"term":"cube root function","def":"The parent function f(x) = ∛x."},{"term":"cubic function","def":"The parent function f(x) = x³."},{"term":"equations/inequalities","def":"A general term covering both equations (statements that two expressions are equal) and inequalities (statements that one expression is greater/less than another), across every function family in the course."},{"term":"exponential function","def":"A function of the form f(x) = bˣ."},{"term":"factor theorem","def":"If f(c) = 0, then (x − c) is a factor of the polynomial f(x) — and vice versa. Used to test or find polynomial factors."},{"term":"independent/dependent variables","def":"The independent variable is the input (x-axis); the dependent variable is the output (y-axis) — it depends on what you put in for the independent one."},{"term":"inverse functions","def":"A pair of functions that undo each other — f(f⁻¹(x)) = x and f⁻¹(f(x)) = x."},{"term":"linear function","def":"The parent function f(x) = x."},{"term":"logarithmic function","def":"A function of the form f(x) = log_b(x)."},{"term":"quadratic function","def":"The parent function f(x) = x²."},{"term":"rational function","def":"The parent function f(x) = 1/x."},{"term":"reasonableness of solutions","def":"Checking whether a solution actually makes sense for the situation — by substituting back into the original equation, or checking a table/graph."},{"term":"remainder theorem","def":"Dividing a polynomial f(x) by (x − c) leaves a remainder equal to f(c) — lets you evaluate a polynomial without direct substitution."},{"term":"representations","def":"The different ways to show the same function: an equation, a table, a graph, or a verbal description."},{"term":"square root function","def":"The parent function f(x) = √x."},{"term":"systems of equations","def":"A set of two or more equations considered together, solved by finding values that satisfy all of them at once."},{"term":"systems of inequalities","def":"A set of two or more inequalities considered together, solved by finding values that satisfy all of them at once."}]},{"unit":13,"title":"Exploring a Business Venture (performance task)","terms":[{"term":"correlation value","def":"A number describing how well a model fits data — r for linear fit strength, r² for any model type\u0027s fit quality."},{"term":"direct variation","def":"A relationship y = kx — as x increases, y increases at a constant rate."},{"term":"domain/range","def":"The set of all possible input values (domain) and output values (range) a function can produce."},{"term":"equations","def":"A mathematical statement that two expressions are equal."},{"term":"exponential function","def":"A function of the form f(x) = bˣ."},{"term":"inequalities","def":"A mathematical statement that one expression is greater than, less than, or not equal to another."},{"term":"inverse variation","def":"A relationship y = k/x — as x increases, y decreases."},{"term":"linear function","def":"The parent function f(x) = x."},{"term":"parent functions","def":"The simplest, unmodified form of a function family."},{"term":"quadratic function","def":"The parent function f(x) = x²."},{"term":"reasonableness of solutions","def":"Checking whether a solution actually makes sense for the situation — by substituting back into the original equation, or checking a table/graph."},{"term":"representations","def":"The different ways to show the same function: an equation, a table, a graph, or a verbal description."},{"term":"scatterplot","def":"A graph of individual data points (x, y) used to look for a pattern or trend before fitting a model."},{"term":"systems of equations","def":"A set of two or more equations considered together, solved by finding values that satisfy all of them at once."},{"term":"systems of inequalities","def":"A set of two or more inequalities considered together, solved by finding values that satisfy all of them at once."},{"term":"x-intercepts","def":"The point(s) where a graph crosses the x-axis. There, y = 0."},{"term":"zeros","def":"The x-value(s) that make a function equal 0 — the same locations as the x-intercepts."}]}];
